{
  "title": "A Gentle Day in Cusco",
  "summary": "A slow wander through the same corner of Cusco, with the planetarium kept for the evening and no long rides anywhere.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "We start here because the market is close, lively, and lets the early birds stretch their legs before the day warms up.",
      "must_do_id": null
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "A short walk from the market, this little chocolate stop keeps the morning easy and gives the history lovers something sweet to chew on.",
      "must_do_id": null
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": "m3",
      "note": "The one thing we keep, and rightly so: a calm evening under the stars, with no rush to get there from our little corner of the city.",
      "must_do_id": "m3"
    }
  ]
}

